(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0001","batch":"01","category":"Categoria B","question":"Dacă ați selectat banda de circulație conform imaginii prezentate, vă este permis:","answers":["Să circulați înainte sau la dreapta","Să virați numai la dreapta","Să circulați numai înainte"],"correctIndices":[0],"correct":0,"explanation":"În această situație vă apropiați de o intersecție în care este obligatoriu să se circule pe una dintre direcțiile înainte sau la dreapta, obligație impusă prin indicatorul de obligare „Înainte sau la dreapta” și prin marcajele prin săgeți pentru selectare pe benzi. Această semnalizare rutieră interzice efectuarea virajului către stânga în această intersecție. Având în vedere că v-ați încadrat pe banda 1 trebuie să respectați semnificația marcajului aplicat pe această bandă, marcaj care vă obligă să circulați pe una dintre direcțiile înainte sau la dreapta, virajul către stânga fiind interzis. Dacă v-ați fi încadrat de banda 2 ar fi trebuit să respectați marcajul aplicat pe acea bandă, marcaj care obligă să se circule doar pe direcția înainte. Prin urmare, dacă ați selectat banda de circula","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0001.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0001.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #1. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 0 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 0","sourceQuestionId":"0","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0002","batch":"01","category":"Categoria B","question":"Care este regula de trecere la întâlnirea acestui indicator?","answers":["Regula priorității de stânga","Regula primului ajuns în intersecție","Regula priorității de dreapta"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul din imagine se numește “Intersecție de drumuri”. Acesta vă avertizează că urmează o intersecție nedirijata de două drumuri de aceeași categorie. La trecerea prin intersecțiile nedirijate aveți obligația de a circula cu o viteză care să nu depăşească 30 km/h în localităţi sau 50 km/h în afara localităţilor și să cedați trecerea vehiculelor care vin din partea dreaptă, mai exact, să aplicați regula priorității de dreapta.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0002.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0002.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #2. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 1 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 1","sourceQuestionId":"1","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/2.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0003","batch":"01","category":"Categoria B","question":"Vă este permis să executați depășirea în situația prezentată?","answers":["Nu, deoarece efectuați manevra pe un pod","Da, întrucât axul drumului nu este marcat cu o linie continuă","Nu, deoarece podul nu are parapeţi din beton"],"correctIndices":[0],"correct":0,"explanation":"În situația dată depășirea autovehiculului din față este interzisă deoarece această manevră este interzisă pe poduri. Trebuie să ținem cont că pe poduri se interzice manevra de depășire, dar cu excepția vehiculelor cu tracțiune animală, motocicletelor fără ataș, mopedelor, bicicletelor și trotinetelor electrice, aceste pot fi depășite dacă vizibilitatea asupra drumului este asigurată pe o distanță mai mare de 20 de metri, iar lățimea drumului este de cel puțin 7 metri, cu condiția să nu se încalce marcajul continuu, dacă un astfel de marcaj există. Pe poduri vă sunt interzise și următoarele manevre: oprirea, staționarea, întoarcerea și mersul înapoi.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0003.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0003.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #3. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 2 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 2","sourceQuestionId":"2","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_3.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0004","batch":"01","category":"Categoria B","question":"De la ce distanță față de vehiculul care circulă din sens opus, pe timp de noapte, sunteți obligat să folosiți luminile de întâlnire?","answers":["De la cel puţin 100 m","De la cel puţin 150 m","De la cel puţin 200 m"],"correctIndices":[2],"correct":2,"explanation":"Trebuie să facem diferența între următoarele două situații pe care le întâlnim în întrebările din chestionare: În cazul acestei întrebări, având în vedere că este vorba despre un vehicul care circulădin sens opus, pe timp de noapte, aveți obligația ca de la distanța de cel puțin200de metri față de acesta să folosiți luminile de întâlnire,concomitent cu reducerea vitezei de deplasare.În cazul în care în acel moment circulați cu luminile de drum (faza lungă) în funcțiune, trebuie să le schimbați cu luminile de întâlnire (faza scurtă), pentru a nu-i deranja pe cei din față, concomitent cu reducerea vitezei de deplasare.În cazul în care în acel moment circulați având în funcțiune, în schimbul luminilorde întâlnire, luminile pentru circulația diurnă (DRL), trebuie să aprindeți luminile de întâl","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0004.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0004.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #4. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 3 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 3","sourceQuestionId":"3","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0005","batch":"01","category":"Categoria B","question":"Ce traseu trebuie să urmați pentru a vira la stânga în intersecție?","answers":["Traseul 1","Traseul 2","Traseul 3"],"correctIndices":[2],"correct":2,"explanation":"În această situație întâlnim indicatorul „Interzis a vira la stânga”, acesta interzice virajul la stânga întrucât executarea virajului ar pune în pericol siguranța celorlalți participanți la trafic. Zona de acțiune a indicatorului se termină după prima intersecție. În cazul de față interzicerea se referă doar la prima posibilitate de viraj către stânga. În această situație întâlnim și indicatorul de orientare „Presemnalizarea traseului de urmat în vederea efectuării virajului la stânga”. Acesta are rolul de a orienta conducătorul de vehicul asupra traseului pe care trebuie să îl urmeze dacă vrea să vireze la stânga. Traseul corect pentru a vira la stânga în această intersecție este semnalizat de indicatorul de orientare prin linia neagră. Prin urmare, în această situație traseul corect pen","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0005.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0005.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #5. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 4 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 4","sourceQuestionId":"4","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_5.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0006","batch":"01","category":"Categoria B","question":"Indicatorul interzice accesul:","answers":["Motocicletelor","Mopedelor","Bicicletelor"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul din imagine face parte din categoria indicatoarelor de interzicere sau restricție și se numește „Accesul interzis mopedelor”. Acest indicator interzice accesul mopedelor pe sectorul de drum la capetele căruia se găsește instalat. Având în vedere că în situația dată dvs. conduceți un autovehicul din categoria B, indicatorul nu vi se adresează și nu aveți nicio obligație. Interzicerea accesului motocicletelor se face prin indicatorul „Accesul interzis motocicletelor”, iar interzicerea accesului bicicletelor se face prin indicatorul „Accesul interzis bicicletelor”.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0006.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0006.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #6. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 5 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 5","sourceQuestionId":"5","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_6.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0007","batch":"01","category":"Categoria B","question":"Indicatorul vă avertizează că urmează:","answers":["Un depou de trenuri","O trecere la nivel cu o cale ferată prevăzută cu bariere","O trecere la nivel cu o cale ferată fără bariere, cu semnalizare luminoasă"],"correctIndices":[2],"correct":2,"explanation":"Ansamblul de indicatoare și panouri adiționale din imagine este format din următoarele trei componente: Având în vedere semnificațiile indicatoarelor, în situația dată sunteți avertizat că la distanța de 150 de metri urmează să întâlniți o trecere la nivel cu calea ferată fără bariere cu instalație de semnalizare automată. În această situație aveți obligația de a reduce viteza de deplasare, vă asigurați că din partea stângă sau din partea dreaptă nu se apropie un vehicul feroviar și traversați calea ferată doar dacă instalația de semnalizare luminoasă automată are în funcțiune lumina de culoare albă intermitentă cu cadență lentă.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0007.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0007.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #7. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 6 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 6","sourceQuestionId":"6","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_7.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0008","batch":"01","category":"Categoria B","question":"Este permisă oprirea în situația dată?","answers":["Da, deoarece stația de tramvai este prevăzută cu refugiu pentru pietoni","Nu","Da, dacă în stație nu se află niciun tramvai"],"correctIndices":[1],"correct":1,"explanation":"Se interzice oprirea voluntară a vehiculelor în stațiile de transport public de persoane, precum și la mai puțin de 25 de metri înainte și după acestea. Deci, în această situație oprirea nu este permisă","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0008.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0008.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #8. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 7 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 7","sourceQuestionId":"7","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_8.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0009","batch":"01","category":"Categoria B","question":"Puteți depăși în situatia dată?","answers":["Da, dacă vă asigurați că manevra poate fi executată și semnalizați corespunzător","Nu, deoarece vizibilitatea este redusă","Nu, deoarece prin această manevră veți trece peste axul drumului"],"correctIndices":[0],"correct":0,"explanation":"În situația din imagine întâlniți un marcaj format dintr-o linie continuă și una discontinuă, alăturate. Marcajul cu linie discontinuă este cel mai apropiat de vehiculul pe care îl conduceți și vă permite trecerea peste acesta. Prin urmare vă este permisă depășirea, dar trebuie să vă asigurați că manevra poate fi executată în condiții de siguranță și să semnalizați corespunzător manevra.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0009.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0009.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #9. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 8 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 8","sourceQuestionId":"8","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_9.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0010","batch":"01","category":"Categoria B","question":"Cum procedați în situația dată?","answers":["Reduceți viteza și la nevoie opriți","Depășiți fără restricții autobuzul","Opriți la 5 m în spatele autobuzului"],"correctIndices":[0],"correct":0,"explanation":"Atunci când vă apropiați de o stație pentru mijloace de transport public de persoane prevăzută cu alveolă, circulând pe banda de lângă acostament sau bordură, iar autobuzul aflat oprit în stație semnalizează intenția de a ieși, aveți obligația de a reduce viteza și la nevoie să opriți pentru a-i permite acestuia să reintre în trafic. Trebuie să reținem că autobuzul al cărui conducător semnalizează intenția de a reintra în trafic din stația prevăzută cu alveolă are prioritate DOAR față de vehiculele care circulă din spatele acestuia, iar dacă drumul are mai multe benzi pe sens acesta are prioritate DOAR față de vehiculele care circulă din spatele acestuia pe prima bandă.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0010.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0010.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #10. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 9 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 9","sourceQuestionId":"9","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_10.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0011","batch":"01","category":"Categoria B","question":"În ce ordine vor circula autovehiculele prin intersecția prezentată, dacă semafoarele nu funcționează?","answers":["Tramvaiul 1, tramvaiul 2, autoturismul","Autoturismul, tramvaiul 1, tramvaiul 2","Tramvaiul 1, autoturismul, tramvaiul 2"],"correctIndices":[1],"correct":1,"explanation":"Semafoarele nu funcționează și trebuie să respectăm semnificația indicatoarelor de reglementare de prioritate. Atenție! Intersecția este tot o intersecție dirijată, deoarece atunci când semafoarele nu funcționează se va respecta semnificația indicatoarelor de reglementare de prioritate,devenind astfel o intersecție cu circulație dirijată prin indicatoare. Având în vedere că intersecția estecu circulație dirijată, iar tramvaiele beneficiază de „prioritate specială” pentru vehiculele care circulă pe șine doar în intersecțiile cu circulație nedirijată, tramvaiele nu beneficiază de „prioritate specială” în această situație. Tramvaiul 2 întâlnește indicatorul „Cedează trecerea” și trebuie să acorde prioritate tramvaiului 1 și autoturismului. Tramvaiul 1 și autoturismul au prioritate deoarece în","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0011.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0011.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #11. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 10 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 10","sourceQuestionId":"10","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_11.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0012","batch":"01","category":"Categoria B","question":"Cum este corect să procedați, dacă vă aflați la volanul autoturismului roșu?","answers":["Circulând spre stânga, vă puteți angaja abia ultimul","Vă angajați primul în traversare","Permiteți trecerea tramvaiului"],"correctIndices":[1],"correct":1,"explanation":"Conducând autoturismul roșu întâlniți indicatorul „Drum cu prioritate” care vă conferă prioritate de trecere și vă veți angaja primul în traversarea intersecției. Tramvaiul și autoturismul albastru întâlnesc indicatorul „Cedează trecerea” și au obligația de a vă acorda prioritate.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0012.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0012.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #12. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 11 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 11","sourceQuestionId":"11","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_12.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0013","batch":"01","category":"Categoria B","question":"Sunteți obligat să opriți vehiculul pe care îl conduceți:","answers":["La semnalul polițistului care dirijează circulația","La semnalul polițistului, dar numai dacă acesta corespunde semnalului de culoare roșie al semaforului","La semnalul pietonilor care traversează strada pe la colțul intersecției fără marcaje"],"correctIndices":[0],"correct":0,"explanation":"Sunteți obligat să opriți vehiculul pe care îl conduceți la semnalele polițistului care dirijează circulația. Semnalele date de acesta se vor respecta cu prioritate, indiferent de situație. Dacă polițistul care dirijează circulația vă adresează unul dintre semnalele de oprire, aveți obligația să respectați semnalul acestuia și să opriți, indiferent de culoarea semaforului sau a altor reguli de circulație. Nu aveți obligația să opriți la semnalul pietonilor care traversează strada pe la colțul intersecției fără marcaje. Aceștia pot traversa strada pe la colțul intersecției, în cazul în care nu se găsește o trecere de pietoni în apropiere, dar nu beneficiază de prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0013.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0013.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #13. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 12 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 12","sourceQuestionId":"12","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0014","batch":"01","category":"Categoria B","question":"Ce semnifică indicatorul împreună cu panoul adițional?","answers":["Sfârșitul zonei de acțiune a indicatorului „staționarea interzisă“","Sfârșitul zonei de acțiune a indicatorului „oprirea interzisă“","Începutul zonei în care este interzisă oprirea"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul din imagine face parte din categoria indicatoarelor de interzicere sau restricție și se numește „Oprirea interzisă”. Acest indicator interzice conducătorului de vehicul să efectueze manevra de oprire în zona de acțiune a acestuia. Panoul adițional instalat sub indicatorul „Oprirea interzisă” se numește „Sfârșitul zonei de acțiune a indicatorului”. Acesta indică locul în care se sfârșește zona de acțiune a indicatorului sub care se află instalat. Prin urmare, indicatorul împreună cu panoul adițional semnifică sfârșitul zonei de acțiune a indicatorului “Oprirea interzisă”. Oprirea vehiculelor fiind interzisă înainte de locul în care se află instalate acestea. Dacă manevra de oprire se efectuează după locul în care este instalat indicatorul împreună cu panoul adițional, aceasta es","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0014.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0014.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #14. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 13 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 13","sourceQuestionId":"13","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_14.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0015","batch":"01","category":"Categoria B","question":"Virați la stânga în intersecție. Cum procedați?","answers":["Acordați prioritate autoturismului din stânga","Aveți prioritate față de autoturismul alb din stânga","Nu vă este permis să virați la stânga"],"correctIndices":[1],"correct":1,"explanation":"Având în vedere că această intersecție nu este dirijată, trebuie să aplicăm regula priorității de dreapta. În această situație autoturismul alb trebuie să vă acorde prioritate deoarece circulați din partea dreaptă a acestuia. Având prioritate, veți pătrunde primul în intersecție.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0015.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0015.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #15. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 14 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 14","sourceQuestionId":"14","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_15.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0016","batch":"01","category":"Categoria B","question":"În care dintre următoarele situații vă este interzis să efectuați depășirea?","answers":["Pe drumurile cu o singură bandă de circulație pe sens","La mai puțin de 150 m de trecerile la nivel cu calea ferată","În zona de acțiune a indicatorului „depășirea interzisă“"],"correctIndices":[2],"correct":2,"explanation":"Pe drumurile cu o singură bandă de circulație pe sens depășirea este permisă. Depășirea este permisă și la mai puțin de 150 de metri de o trecere la nivel cu o cale ferată, depășirea fiind interzisă pe trecerea la nivel cu calea ferată și la mai puțin de 50 de metri înainte de aceasta. La întâlnirea indicatorului „Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă” vă este interzisă depășirea tuturor autovehiculelor, cu excepția motocicletelor fără ataș și a vehiculelor simple, ca de exemplu biciclete.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0016.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0016.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #16. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 15 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 15","sourceQuestionId":"15","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0017","batch":"01","category":"Categoria B","question":"Cu ce viteză veți circula în condiții de ceață, ploi torențiale, ninsori abundente, dacă vizibilitatea este redusă sub 100 m?","answers":["Maxim 50 km/h în localități sau 60 km/h în afara localităților","Reduceți viteza până la limita evitării oricărui pericol","Maxim 30 km/h în localități sau 50 km/h în afara localităților"],"correctIndices":[2],"correct":2,"explanation":"În condițiile atmosferice din enunțul întrebării aveți obligația să circulați cu o viteză care să nu depășească 30 de km/h în localități și 50 de km/h în afara localităților. Vezi explicația de la varianta C de răspuns. Obligația de a reduce viteza până la limita evitării oricărui pericol o aveți în toate situațiile, nu doar în condiții atmosferice din enunțul întrebării. Prin urmare varianta B nu este corectă. Atunci când vizibilitatea este redusă sub 100 de metri, în condiții de ceață, ploi torențiale sau ninsori abundente, aveți obligația să circulați cu o viteză care să nu depășească 30 de km/h în localități și 50 de km/h în afara localităților.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0017.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0017.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #17. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 16 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 16","sourceQuestionId":"16","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0018","batch":"01","category":"Categoria B","question":"Imobilizarea unui braț fracturat se face:","answers":["În dreptul osului fracturat","Cuprinzând osul fracturat și articulația superioară","Cuprinzând osul fracturat și cele două articulații, respectiv cea superioară și inferioară"],"correctIndices":[2],"correct":2,"explanation":"Imobilizarea unei fracturi la mâini se face prin fixarea cu atele a două articulații învecinate fracturii, mai sus și mai jos de locul fracturii. Sub atelă se aplică bandaj moale de tifon (sau vată) pentru prevenirea lezării țesuturilor moi. În cazul în care nu se dispune de atele, imobilizarea se poate face cu eșarfe sau triunghiuri de pânză.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0018.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0018.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #18. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 17 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 17","sourceQuestionId":"17","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0019","batch":"01","category":"Categoria B","question":"Care dintre următorii factori reprezintă baza conduitei preventive?","answers":["Cunoașterea normelor de circulație și a regulilor de conducere a autovehiculului","Capacitatea de a fi politicos și disciplinat în traficul rutier","Încadrarea în baremele legale privind sănătatea"],"correctIndices":[0,1],"correct":0,"explanation":"Dintre cele trei variante de răspuns cele care reprezintă baza conduitei preventive sunt: „cunoașterea normelor de circulație și a regulilor de conducere a autovehiculului” și „capacitatea de a fi politicos și disciplinat în traficul rutier”. Dacă starea de sănătate nu se încadrează în baremele legale privind sănătatea, nu mai poate fi vorba de o conduită preventivă, în acest caz nu se mai poate conduce deloc, până la rezolvarea problemelor de sănătate, dacă acestea se pot rezolva. Conducerea preventivă (conduita preventivă) - reprezintă comportamentul conducătorului auto caracterizat prin următoarele trăsături esențiale: În concluzie, prin conduită preventivă se înțelege comportamentul rutier care asigură prevenirea accidentelor, prin anticiparea și evitarea acțiunilor incorecte ale parte","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0019.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0019.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #19. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 18 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 18","sourceQuestionId":"18","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0020","batch":"01","category":"Categoria B","question":"Ce vă indică, de regulă, faptul că bateria de acumulatori este descărcată?","answers":["La aprinderea farurilor, intensitatea luminoasă a acestora scade progresiv","Acționând claxonul, acesta emite un sunet slab, întrerupt","Demontând bateria, constatăm că aceasta este mai ușoară decât de obicei"],"correctIndices":[0,1],"correct":0,"explanation":"Principalele semne care indică faptul că bateria de acumulatori este descărcată sunt următoarele: la aprinderea farurilor, intensitatea luminoasă a acestora scade progresiv iar la acționarea claxonului acesta emite un sunet slab și întrerupt. Bateria nu își va schimba greutatea dacă este sau nu descărcată.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0020.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0020.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #20. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 19 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 19","sourceQuestionId":"19","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0021","batch":"01","category":"Categoria B","question":"Pe ce drumuri sunt permise oprirea și staționarea vehiculelor și pe partea stângă, în sensul de mers?","answers":["Pe drumurile cu trafic redus","Pe drumurile cu sens unic, dacă rămâne liberă cel puțin o bandă de circulație","Pe orice drum"],"correctIndices":[1],"correct":1,"explanation":"În localități, pe drumurile cu sens unic, oprirea sau staționarea voluntară a vehiculelor este permisă și pe partea stângă, dacă rămâne liberă cel puțin o bandă de circulație.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0021.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0021.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #21. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 20 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 20","sourceQuestionId":"20","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0022","batch":"01","category":"Categoria B","question":"Ce trebuie să faceți pentru a evita un accident de circulație?","answers":["Să nu conduceți autoturismul decât atunci când probleme grave impun acest lucru","Să vă asigurați întotdeauna un partener care să cunoască bine traseul parcurs","Să anticipați și să contracarați la timp manevrele imprudente ale partenerilor de drum și să respectați permanent regulile de circulație"],"correctIndices":[2],"correct":2,"explanation":"Pentru prevenirea accidentelor de circulație trebuie să anticipați și să contracarați la timp manevrele imprudente ale partenerilor de drum și să respectați permanent regulile de circulație. Pentru siguranța rutieră este important ca prezența celorlalți participanți la trafic să fie detectată la timp. Detectarea mai bună și mai timpurie a celorlalți participanți la trafic duce la luarea de măsuri din timp pentru evitarea unei coliziuni sau pentru reducerea gravității accidentului datorită vitezei mai mici la impact. Pentru autovehicule, sistemul de iluminare este modalitatea generală de a spori vizibilitatea. Luminile pot de asemenea contribui la creșterea vizibilității în timpul zilei. Pentru toți participanții la trafic neprotejați, pietonii, conducătorii mopedelor și ai motocicletelor, ","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0022.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0022.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #22. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 21 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 21","sourceQuestionId":"21","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0023","batch":"01","category":"Categoria B","question":"Ce obligație are conducătorul unui autovehicul imobilizat într-un pasaj subteran?","answers":["Să oprească motorul și să acționeze luminile de avarie","Să tracteze autovehiculul până la ieșirea din pasajul subteran","Să anunțe imediat pompierii în legătură cu locul în care se află"],"correctIndices":[0],"correct":0,"explanation":"Pentru variantaA În cazul în care rămâneți în pană cu autovehiculul într-un tunel, aveți obligația de a opri funcționarea motorului, de a pune în funcțiune luminile de avarie și de a instala triunghiurile reflectorizante la cel puțin 30 de metri înainte și după autovehicul. Nu aveți obligația să tractați autovehiculul până la ieșirea din pasajul subteran și nici să anunțați pompierii, aceștia vor fi anunțați doar pentru descarcerare sau în caz de incendiu, prin serviciul de urgență 112.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0023.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0023.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #23. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 22 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 22","sourceQuestionId":"22","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0024","batch":"01","category":"Categoria B","question":"Care dintre tipurile de semnalizare de mai jos vor fi respectate cu prioritate?","answers":["Semnalele luminoase","Semnalizarea temporară, care modifică regimul normal de desfășurare a circulației","Semnalele și indicațiile polițistului"],"correctIndices":[2],"correct":2,"explanation":"Participanții la trafic trebuie să respecte regulile de circulație, semnalele, indicațiile și dispozițiile polițistului rutier, precum și semnificația diferitelor tipuri de mijloace de semnalizare rutieră, în următoarea ordine de prioritate:","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0024.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0024.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #24. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 23 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 23","sourceQuestionId":"23","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0025","batch":"01","category":"Categoria B","question":"Când măsurați presiunea din pneuri?","answers":["Înaintea plecării în cursă, când pneurile sunt reci","După parcurgerea a cel puțin 400-500 km, când pneurile sunt calde","Doar atunci când observăm că autovehiculul este înclinat într-o parte"],"correctIndices":[0],"correct":0,"explanation":"Presiunea din anvelope trebuie măsurată înaintea unui drum lung, atunci când pneurile sunt reci, în medie, cel puțin o dată pe lună. Dacă se va măsura la cald, se vor obține presiuni ușor mai mari, deoarece aerul se va dilata de la caldură. Presiunea în pneuri este foarte importantă deoarece o presiune corectă va asigura un timp și o distanță de frânare optimă, asigură o stabilitate optimă în curbe și o durată de viață mai lungă a anvelopelor. Presiunea corectă nu este specificată pe anvelopă, ci pe tocul portierei, lângă rezervorul de combustibil sau în manualul mașinii.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0025.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0025.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #25. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 24 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 24","sourceQuestionId":"24","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0026","batch":"01","category":"Categoria B","question":"În care dintre situații se suspendă exercitarea dreptului de a conduce?","answers":["În cazul depășirii în mod repetat, cu mai mult de 20 km/h, a vitezei maxime legale","În cazul neopririi la semnalul agentului de cale ferată","În cazul neprezentării în termen de 24 de ore la unitatea de poliție competentă pe raza căreia s-a produs un accident soldat cu avarierea vehiculului"],"correctIndices":[2],"correct":2,"explanation":"Depășireacu mai mult de 20 km/ha vitezei maxime admise, fie că aceasta se face sau nu în mod repetat, se sancționează cuamendă contravenționalăși cuaplicarea punctelor de penalizare, în funcție de valoarea cu care s-a depășit limita maximă de viteză. Sancționarea cu suspendarea exercitării dreptului de a conduce pentru o perioada de 90 sau de 120 de zile și cu amenda contravențională prevăzută în clasa a IV-a de sancțiuni, se aplică pentru depășirea vitezei maxime admisecu mai mult de 50 km/hrespectivcu mai mult de 70 km/h. Neoprirea sau nerespectarea semnificației semnalelor regulamentare ale agenților de cale ferată care dirijează circulația la trecerile la nivel cu calea ferată se sancționează cu amenda prevăzută în clasa a IV-a de sancțiuni și cu aplicarea a 6 puncte de penalizare. Pen","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0026.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0026.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #26. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 25 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 25","sourceQuestionId":"25","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0027","batch":"01","category":"Categoria B","question":"Semnalul polițistului rutier aflat într-un autovehicul al poliției, efectuat cu brațul, cu sau fără baston reflectorizant, scos pe partea laterală dreaptă a vehiculului, semnifică:","answers":["Oprire pentru conducătorii vehiculelor care circulă în spatele autovehiculului poliției","Reducerea vitezei de către cei care circulă în spatele autovehiculului poliției","Semnalul se adresează celor care circulă din sens opus"],"correctIndices":[0],"correct":0,"explanation":"Semnalul polițistului aflat în autovehiculul de poliție, prin scoaterea brațului cu sau fără baston reflectorizant pe partea laterală dreaptă a autovehiculului, semnifică oprire pentru conducătorii vehiculelor care circulă în spatele autovehiculului poliției.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0027.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0027.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #27. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 26 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 26","sourceQuestionId":"26","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0028","batch":"01","category":"Categoria B","question":"Ce reprezintă distanța de 50 m necesară pentru semnalizarea schimbării direcției de mers în localități?","answers":["Distanța față de vehiculul care se deplasează în spatele dvs.","Distanța față de locul în care se termină executarea manevrei de depășire","Distanța dintre locul în care se semnalizează intenția de a depăși și locul în care se începe manevra"],"correctIndices":[2],"correct":2,"explanation":"Intenția conducătorilor de autovehicule de a schimba direcția de deplasare se semnalizează prin punerea în funcțiune a luminilor indicatoare de direcție, cu cel puțin 50 de metri în localități și 100 de metri în afara localităților, înaintea începerii manevrei. Distanța de 50 metri necesară pentru semnalizarea schimbării direcției de mers în localități reprezintă distanța dintre locul în care se semnalizează intenția de a depăși și locul în care se începe manevra. Adică distanța parcursă cu semnalizatorul în funcțiune până la începerea manevrei.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0028.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0028.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #28. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 27 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 27","sourceQuestionId":"27","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0029","batch":"01","category":"Categoria B","question":"Puteți depăși tramvaiul oprit într-o stație fără refugiu pentru pietoni, pe o stradă cu sens unic?","answers":["Da, dar numai pe partea stângă","Da, dar numai dacă nu există pietoni în stația de tramvai","Nu, deoarece depășirea este interzisă"],"correctIndices":[2],"correct":2,"explanation":"Atunci când întâlniți un tramvai oprit într-o stațiefără refugiupentru pietoni,indiferent dacă drumul este sau nu cu sens unic, vă este interzisă depășirea acestuia, având obligația de a opri în spatele tramvaiului și vă puteți relua deplasarea numai după ce ușile tramvaiului s-au închis și v-ați asigurat că nu puneți în pericol siguranța pietonilor angajați în traversarea drumului public.Atenție!Depășirea este interzisă și pe partea stângă și pe partea dreaptă și indiferent dacă există sau nu pietoni care doresc să urce sau să coboare din tramvai.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0029.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0029.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #29. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 28 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 28","sourceQuestionId":"28","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0030","batch":"01","category":"Categoria B","question":"Viteza de deplasare trebuie să nu depășească 30 km/h în localități sau 50 km/h în afara localităților:","answers":["La întâlnirea indicatorului „drum cu prioritate“","În curbe deosebit de periculoase semnalizate ca atare sau în care vizibilitatea este mai mică de 50 m","Atunci când se circulă în aceeași direcție cu autobuzele oprite în stație, pe drumurile cu o singură bandă pe sens"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutieră nu obligă să se circule cu o viteză care să nu depășească 30 km/h în localități la întâlnirea indicatorului „Drum cu prioritate”. Acest indicator vă informează că circulați pe drumul cu prioritate. Atunci când se circulă prin curbe deosebit de periculoase semnalizate ca atare sau în care vizibilitate este mai mică de 50 metri, viteza de deplasare nu trebuie să depășească 30 km/h în localități și 50 km/h în afara localităților. Atunci când se circulă în aceeași direcție cu autobuzele sau orice alte mijloace de transport public de persoane, care sunt oprite în stație,NU aveți obligațiasă circulați cu o viteză care să nu depășească30 km/h în localitățisau50 km/h în afara localităților, indiferent dacă drumul are o singură bandă sau mai multe benzi pe sensul de mers, dar, di","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0030.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0030.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #30. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 29 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 29","sourceQuestionId":"29","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0031","batch":"01","category":"Categoria B","question":"Se interzice depășirea:","answers":["Atunci când se încalcă marcajul continuu longitudinal","În zonele cu trafic intens","Când se încalcă marcajul discontinuu longitudinal"],"correctIndices":[0],"correct":0,"explanation":"Legislația rutieră interzice efectuarea manevrei de depășire a vehiculelor atunci când pentru efectuarea acesteia se încalcă marcajul continuu, simplu sau dublu, care desparte sensurile de mers, iar autovehiculul circulă, chiar și parțial, pe sensul opus, ori se încalcă marcajul care delimitează spațiul de interzicere.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0031.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0031.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #31. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 30 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 30","sourceQuestionId":"30","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0032","batch":"01","category":"Categoria B","question":"Ce le este interzis conducătorilor de autovehicule și de tramvaie?","answers":["Să folosească telefoanele mobile în timpul mersului, fără să aibă sistem de tip „mâini libere“","Să folosească luminile de avarie în localități","Să se angajeze în discuții cu alți pasageri"],"correctIndices":[0],"correct":0,"explanation":"Conducătorilor de autovehicule sau tramvaie le este interzisă utilizarea telefoanelor mobile, atunci când aceștia se află în timpul mersului, excepție de la această interzicere fac situațiile în care telefoanele mobile sunt dotate cu dispozitive tip \"mâini libere\". Este permisă folosirea luminilor de avarie, dar bineînțeles acestea se vor folosi doar în cazurile justificate. Angajarea în discuții cu alți pasageri nu i se interzice, în schimb, i se interzice în timpul mersului sa aibă preocupări de natură a-i distrage în mod periculos atenția ori să folosească instalații de sonorizare la un nivel de zgomot care ar afecta deplasarea în siguranță, a lui și a celorlalți participanți la trafic.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0032.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0032.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #32. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 31 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 31","sourceQuestionId":"31","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0033","batch":"01","category":"Categoria B","question":"Ce trebuie să conțină biletul care se prinde lângă garoul aplicat unei persoane rănite?","answers":["Datele de stare civilă ale persoanei","Poziția în care a fost găsită victima","Ora și minutul aplicării garoului"],"correctIndices":[2],"correct":2,"explanation":"Garoul este un cordon elastic, care este folosit pentru oprirea sângerării în cazul unor hemoragii care nu pot fi oprite altfel, de obicei în cazul plăgilor membrelor. Acesta se aplică deasupra rănii, pentru a micșora presiunea arterială în zona plăgii. Acesta nu se aplică direct pe piele ci peste o bucată de fașă sau alt material moale și se atașează neapărat un bilet pe care se notează numele victimei și ora exactă a aplicării garoului. În absența unui garou, se poate folosi: un fular, cordon, curea, cravată, șnur, elastic etc. Deși în trecut se recomanda slăbirea garoului la fiecare 15 minute pentru a permite alimentarea cu sânge a membrului, practică nu mai este recomandată în prezent, deoarece poate agrava starea victimei. Consultați personalul specializat prin apel 112 înainte de a e","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0033.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0033.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #33. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 32 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 32","sourceQuestionId":"32","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0034","batch":"01","category":"Categoria B","question":"Ce obligații vă revin la executarea manevrei de trecere a vehiculului de pe o bandă pe alta?","answers":["Să semnalizați din timp și să vă asigurați că puteți efectua manevra fără a perturba circulația sau fără a pune în pericol siguranța celorlalți participanți la trafic","Să vă asigurați din spate","Să vă asigurați din față și din spate"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul care dorește să treacă de pe o bandă de circulație pe altă bandă, are obligația să se asigure că poate efectua manevra fără să perturbe circulația sau să pună în pericol siguranța celorlalți participanți la trafic și să semnalizeze din timp manevra, prin punerea în funcțiune a luminilor indicatoare de direcție cu cel puțin 50 m în localități și 100 m în afara localităților înainte de începerea efectuării manevrei, după care poate trece pe respectiva bandă de circulație.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0034.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0034.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #34. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 33 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 33","sourceQuestionId":"33","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0035","batch":"01","category":"Categoria B","question":"Limita maximă de viteză pe care administratorul drumului public o poate stabili pe anumite sectoare, din interiorul localităților, pentru autovehiculele din categoriile A și B, nu poate fi mai mare de:","answers":["50 km/h","80 km/h","110 km/h"],"correctIndices":[1],"correct":1,"explanation":"Limita maximă de viteză în localități este de 50 km/h. Însă pe anumite sectoare de drum din interiorul localităților, administratorul drumului poate stabili, pentru autovehiculele din categoriile A și B și limite de viteză superioare,dar nu mai mult de 80 km/h. Acesta poate stabili în localități și limite de viteză inferioare, dar nu mai puțin de 10 km/h pentru tramvaie și de 30 de km/h pentru toate autovehiculele.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0035.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0035.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #35. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 34 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 34","sourceQuestionId":"34","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0036","batch":"01","category":"Categoria B","question":"Ce categorii de vehicule au obligația de a folosi luminile de întâlnire pe timp de zi?","answers":["Motocicletele și mopedele","Autovehiculele care însoțesc coloane militare sau transportă grupuri de persoane","Autovehiculele care tractează alte vehicule sau care transportă produse periculoase"],"correctIndices":[0,1,2],"correct":0,"explanation":"Folosirea luminilor de întâlnire pe timpul zilei este obligatorie pentru: Deși legislația rutieră a fost actualizată iar în acest moment este obligatoriu ca la circulațiape timpul zilei, pe toate categoriile de drum public, să se circule având în funcțiune luminile de întâlnire (faza scurtă)sauluminile pentru circulația diurnă (DRL), răspunsul la această întrebare rămâne în continuare corect și conform cu legislația. Pentru a înțelege mai bine această regulă dăm următorul exemplu: Un conducător de autovehicul circulă pe timpul zilei,în condiții normale, caz în care are obligația de a pune în funcțiunefie luminile de întâlnire(adică faza scurtă),fie luminile pentru circulația diurnă(DRL), după cum consideră acesta, ori poate chiar să le folosească pe ambele în același timp. Însă dacă acesta","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0036.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0036.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #36. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 35 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 35","sourceQuestionId":"35","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0037","batch":"01","category":"Categoria B","question":"Este permisă staționarea vehiculelor în zona de acțiune a indicatorului „Drum îngustat“?","answers":["Da","Nu","Legea nu prevede nimic cu privire la acest aspect"],"correctIndices":[1],"correct":1,"explanation":"Se interzice staționarea voluntară a vehiculelor în toate cazurile în care este interzisă oprirea voluntară. Astfel, în zona de acțiune a indicatorului „Drum îngustat” staționarea voluntară a vehiculelor este interzisă, deoarece în această situație se interzice oprirea voluntară. În zona de acțiune a acestui indicator sunt interzise manevrele de oprire, staționare, mers înapoi și întoarcere. Manevra de depășire nu este interzisă.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0037.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0037.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #37. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 36 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 36","sourceQuestionId":"36","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0038","batch":"01","category":"Categoria B","question":"Sunteți depășit de un autovehicul care a apreciat greșit distanța și viteza cu care se apropie din sens opus un alt vehicul. Cum trebuie să procedați pentru a evita un accident rutier?","answers":["Măriți viteza de deplasare, pentru a-l determina pe cel ce vă depășește să renunțe la manevră","Claxonați și îi faceți semn cu brațul să nu mai depășească","Reduceți imediat viteza și circulați cât mai aproape de marginea din dreapta a părții carosabile, pentru a-i permite efectuarea depășirii și reintrarea pe sensul normal de mers"],"correctIndices":[2],"correct":2,"explanation":"Atunci când sunteți depășit de un autovehicul care a apreciat greșit distanța și viteza cu care se apropie din sens opus un alt vehicul, trebuie să reduceți viteza și să circulați cât mai aproape de marginea din dreapta a părții carosabile, pentru a-i permite acestuia efectuarea depășirii și reintrarea pe sensul normal de mers. Astfel evitați producerea unui accident rutier. La fel trebuie să procedați și în situația în care din sens opus depășește un autovehiculul care a apreciat greșit distanța și viteza cu care vă apropiați.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0038.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0038.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #38. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 37 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 37","sourceQuestionId":"37","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0039","batch":"01","category":"Categoria B","question":"Aveți posibilitatea de a circula pe drumurile publice cu vehiculul avariat:","answers":["Cel mult 10 zile de la data constatării evenimentului","Până la expirarea asigurării obligatorii de răspundere civilă auto","Cel mult 30 zile de la data producerii avariei"],"correctIndices":[2],"correct":2,"explanation":"Conducătorului de autovehicul îi este interzis să circule cu autovehiculul avariat mai mult de 30 de zile de la producerea avariei.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0039.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0039.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #39. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 38 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 38","sourceQuestionId":"38","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0040","batch":"01","category":"Categoria B","question":"Cum trebuie așezată într-un mijloc de transport o persoană rănită, care prezintă leziuni ale coloanei vertebrale?","answers":["În poziție șezândă","Orizontal, cu fața în sus","Persoana nu trebuie mișcată până la sosirea ambulanței"],"correctIndices":[2],"correct":2,"explanation":"În cazul în care la persoana implicată într-un accident de circulație se suspectează o fractură de coloana vertebrală, se va evita mobilizarea (mișcarea) victimei până la sosirea echipei medicale. Dacă există un potențial pericol (pericol de ardere, asfixiere, etc.) și victima trebuie mobilizată, aceasta se va face cu imobilizarea coloanei vertebrale. Victima va fi culcată pe un plan dur (ușă, scândură, targă) și fixată cu legături trecute peste coapse, bazin și torace. Atenție! Mobilizarea victimei se va face doar în caz de urgență. Puteți bănui că o persoană prezintă o leziune a coloanei vertebrale dacă:","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0040.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0040.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #40. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 39 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 39","sourceQuestionId":"39","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0041","batch":"01","category":"Categoria B","question":"Care sunt factorii care fac ca motorul Diesel al unui autoturism să emită fum excesiv?","answers":["Lipsa combustibilului","Bușonul rezervorului închis la maximum","Defecțiuni la instalația de injecție"],"correctIndices":[2],"correct":2,"explanation":"Lipsa combustibilului va duce la funcționarea cu întreruperi a motorului până la oprirea definitivă a acestuia. Bușonul rezervorului trebuie să stea închis la maximum pentru a nu permite pătrunderea altor lichide în rezervor. Instalația de injecție la un motor Diesel este o instalație de mare precizie și este formată din pompa de injecție care trimite motorina cu presiune mare spre injectoare, în ordinea de aprindere, prin intermediul conductelor de înaltă presiune și reglează debitul de motorină în funcție de regimul de funcționare, conductele de înaltă presiune transportă carburantul de la pompa la injectoare, injectoare care dozează și pulverizează carburantul în camera de ardere a pistonului. Dacă există defecțiuni la instalația de injecție, poate pătrunde prea multă motorină în cilind","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0041.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0041.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #41. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 40 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 40","sourceQuestionId":"40","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0042","batch":"01","category":"Categoria B","question":"Ce semnifică indicatorul din imagine?","answers":["„accesul interzis copiilor neînsoțiți“","„copii“","„trecere obligatorie pentru copii“"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul din imagine face parte din categoria indicatoarelor de avertizare și se numește „Copii”. Acest indicator vă avertizează că urmează să întâlniți un loc frecventat de copii, cum ar fi școli, grădinițe, locuri de joacă, parcuri, etc.. Este indicat să sporiți atenția pentru a putea opri în siguranță în cazul apariției pe neașteptate a copiilor pe partea carosabilă. Legislația rutieră obligă conducătorii de vehicule care întâlnesc indicatorul „Copii” să circule cu o viteză caresă nu depășească 30 km/h în localități sau 50 km/h în afara localitățilorîn intervalul orar 7:00 - 22:00.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0042.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0042.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #42. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 41 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 41","sourceQuestionId":"41","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_43.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0043","batch":"01","category":"Categoria B","question":"Cum trebuie să procedați în această situație?","answers":["Reduceți viteza și vă continuați deplasarea","Opriți și așteptați următorul semnal al polițistului","Circulați obligatoriu pe direcția indicată de brațul polițistului"],"correctIndices":[1],"correct":1,"explanation":"Polițistul rutier execută un semnal cu brațul stâng întins orizontal, acest semnal semnifică oprire pentru participanții la trafic a căror direcție inițială de deplasare se intersectează cu brațul acestuia. În această situație direcția dumneavoastră de deplasare se intersectează cu brațul polițistului și trebuie să opriți, așteptând următorul semnal al polițistului.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0043.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0043.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #43. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 42 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 42","sourceQuestionId":"42","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_44.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0044","batch":"01","category":"Categoria B","question":"Care este traseul optim pentru a întoarce în intersecția prezentată?","answers":["Traseul 1","Traseul 2","Traseul 3"],"correctIndices":[1],"correct":1,"explanation":"În această intersecție circulația se desfășoară în sens giratoriu. Se recomandă conducătorilor de vehicule care doresc să circule printr-o intersecție cu sens giratoriu să se angajeze pe benzile de circulație din interiorul acesteia, în funcție de direcția dorită de deplasare, după cum urmează: Prin urmare, pentru a întoarce autovehiculul în această intersecție cu sens giratoriu, dintre cele trei trasee indicate, traseul numărul 2 este cel optim.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0044.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0044.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #44. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 43 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 43","sourceQuestionId":"43","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_45.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0045","batch":"01","category":"Categoria B","question":"Cum veți proceda în această situație?","answers":["Urmați vehiculul care execută depășirea","Rămâneți în spatele camionului","Indicatorul se adresează vehiculelor care circulă din sens opus"],"correctIndices":[1],"correct":1,"explanation":"În această situație, având în vedere semnificația indicatorului de orientare, care ne informează că peste 150 de metri banda de circulație din partea stângă se va termina, trebuie să rămâneți în spatele autocamionului. Dacă ați fi trecut pe banda a doua, ați fi fost nevoit ca peste 150 de metri să reveniți pe prima bandă, deoarece banda a doua se termină. Trebuie să ținem cont că manevra de depășire creează obligații atât pentru cel care depășește, cât și pentru cel care urmează să fie depășit. Printre obligațiile celui care execută manevra de depășire se numără și obligația să reintre pe banda sau în șirul de circulație inițial după ce a semnalizat și s-a asigurat că poate efectua această manevră în condiții de siguranță pentru vehiculul depășit și pentru ceilalți participanți la trafic. ","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0045.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0045.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #45. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 44 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 44","sourceQuestionId":"44","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_46.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0046","batch":"01","category":"Categoria B","question":"Cum trebuie să procedați dacă virați la stânga?","answers":["Cedați trecerea autovehiculului alb","Accelerați, pentru a nu vă intersecta cu autovehiculul alb","Executați manevra cu luminile de avarie aprinse"],"correctIndices":[0],"correct":0,"explanation":"Conducătorii vehiculelor care virează spre stânga în intersecții, sunt obligați să acorde prioritate de trecere vehiculelor cu care se intersectează și care circulă din partea dreaptă. Prin urmare, dacă doriți să virați la stânga în această intersecție, aveți obligația să cedați trecerea autovehiculului alb, deoarece dvs. virând către stânga, acesta vă vine din partea dreaptă, după care vă puteți continua virajul la stânga.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0046.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0046.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #46. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 45 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 45","sourceQuestionId":"45","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_47.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0047","batch":"01","category":"Categoria B","question":"Care este ordinea de trecere prin intersecție a autoturismelor?","answers":["Roșu, verde, albastru","Verde, albastru, roșu","Albastru, verde, roșu"],"correctIndices":[1],"correct":1,"explanation":"Intersecția din imagine este dirijată cu indicatoare de reglementare de prioritate. Autoturismul verde vine de pe drumul cu prioritate și are prioritate de trecere față de celelalte autoturisme care întâlnesc indicatorul „Cedează trecerea”. Între autoturismul albastru și cel roșu s-a creat o situație de egalitate, ambele întâlnind indicatorul „Cedează trecerea”, însă autoturismul roșu îi va acorda prioritate de trecere autoturismului albastru deoarece virând către stânga, autoturismul albastru îi vine din partea dreaptă. Ordinea de trecere este următoarea: autoturismul verde, urmat de autoturismul albastru iar ultimul prin intersecție va trece autoturismul roșu.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0047.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0047.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #47. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 46 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 46","sourceQuestionId":"46","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_48.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0048","batch":"01","category":"Categoria B","question":"Ce obligații vă revin dacă, într-o intersecție, virați la stânga pe semnalul verde al semaforului?","answers":["Nicio obligație","Acordați prioritate de trecere mijloacelor de transport public de persoane","Acordați prioritate de trecere atât vehiculelor care circulă din sens opus, cât și pietonilor aflați în traversare pe sensul dumneavoastră de mers"],"correctIndices":[2],"correct":2,"explanation":"Atunci când virați către stânga într-o intersecție, la culoarea verde a semaforului, aveți obligația să acordați prioritate de trecere vehiculelor cu care vă intersectați și circulă din partea dreaptă, mai exact celor care circulă din sens opus, dar și pietonului care traversează regulamentar strada pe care doriți să intrați, atunci când acesta se află pe sensul dumneavoastră de mers. Nu aveți o obligație specială față de mijloacele de transport public de persoane în această situație, acestora le acordați prioritate, așa cum le acordați și celorlalte vehicule, dacă circulă vin din sens opus.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0048.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0048.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #48. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 47 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 47","sourceQuestionId":"47","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0049","batch":"01","category":"Categoria B","question":"În care dintre următoarele situații conducătorilor de vehicule le este interzis să execute virajul spre stânga la lumina de culoare verde a semaforului electric?","answers":["Când întâlnesc indicatorul „înainte sau la stânga“","Când se află pe o stradă cu sens unic","Când întâlnesc indicatorul „înainte sau la dreapta“"],"correctIndices":[2],"correct":2,"explanation":"Pentru variantaA Dacă lângă semaforul de culoare verde se întâlnește indicatorul „Înainte sau la stânga”, aveți obligația să vă deplasați doar pe direcțiile înainte sau la stânga, prin urmare NU vă este interzis virajul către stânga la întâlnirea indicatorului „Înainte sau la stânga”. Pe străzile cu circulație în sens unic vă este permis să executați viraje spre stânga sau dreapta, dacă semnalizarea rutieră nu interzice acest lucru. Prin urmare NU va este interzis virajul către stânga pe străzile cu sens unic. Dacă lângă semaforul de culoare verde se întâlnește indicatorul „Înainte sau la dreapta”, aveți obligația să vă deplasați doar pe direcțiile înainte sau la dreapta,virajul către stânga fiind interzis.","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0049.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0049.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #49. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 48 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 48","sourceQuestionId":"48","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0050","batch":"01","category":"Categoria B","question":"La intersecțiile fără marcaje, conducătorii de vehicule care vor să circule pe direcția înainte vor ocupa:","answers":["Rândul din stânga","Rândul din dreapta","Oricare dintre rânduri"],"correctIndices":[2],"correct":2,"explanation":"La intersecțiile fără marcaje de delimitare a benzilor, conducătorii vehiculelor ocupa în mers, cu cel puțin 50 m înainte de intersecție, următoarele poziții:","imageUrl":"/nivel-1/quiz-images/rodrive-b01/0050.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-b01/0050.svg","imageAlt":"Ilustrație proprie Pixel Drive pentru situația rutieră #50. Verifică referința originală la sursă.","imageCredit":"Ilustrație originală Pixel Drive · schematică, verifică sursa","source":"RoDrive · ID 49 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceLabel":"Vezi întrebarea sursă · RoDrive ID 49","sourceQuestionId":"49","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
